"""Step 3 interactive report: controlled stop comparison and dollar reconciliation."""
import csv
import json
import statistics
from pathlib import Path
from plotly.offline import get_plotlyjs

OUTPUT=Path(__file__).resolve().parents[3]/'docs/temp/step3'
SCOPES=['Priority assets','Whole universe','Watchlist ETFs & crypto','Bonds','Major companies','Other instruments']


def aggregate(result):
    fields=result['metadata']['fields']
    by_config={}
    for s in result['instruments']:
        for values in s['rows']:
            r=dict(zip(fields,values))
            by_config.setdefault((r['config'],r['mode']),[]).append((s,r))
    out=[]
    median=lambda values:statistics.median(values) if values else None
    for scope in SCOPES:
        for (config,mode),items in by_config.items():
            rows=[r for s,r in items if scope=='Whole universe' or scope=='Priority assets' and s['priority']
                  or scope=='Watchlist ETFs & crypto' and s['group']=='Watchlist' or s['group']==scope]
            eligible=[r for r in rows if r['common_days']>=730.5]
            scores=[-1 if r['exhausted'] else r['common_cagr'] for r in eligible]
            out.append({'scope':scope,'config':config,'mode':mode,'instruments':len(rows),'eligible':len(eligible),
                        'positive_net':sum(r['net']>0 and not r['exhausted'] for r in rows),
                        'positive_gross':sum(r['gross']>0 and not r['gross_exhausted'] for r in rows),
                        'positive_common':sum(r['common_net'] is not None and r['common_net']>0 and not r['exhausted'] for r in eligible),
                        'median_cagr':median(scores),'median_drawdown':median([-1 if r['exhausted'] else r['common_drawdown'] for r in eligible]),
                        'median_full_return':median([r['net'] for r in rows]),
                        'thin_samples':sum(r['common_trades']<5 for r in eligible),
                        'exhausted':sum(bool(r['exhausted']) for r in rows),
                        'trades':sum(r['trades'] for r in rows),
                        'channel_exits':sum(r['channel_exits'] for r in rows),
                        'initial_exits':sum(r['initial_exits'] for r in rows),
                        'trailing_exits':sum(r['trailing_exits'] for r in rows)})
    return out


def main():
    result=json.loads((OUTPUT/'results.json').read_text(encoding='utf-8'))
    meta=result['metadata']
    assert not meta['partial'],'Complete the full run before publishing the report'
    grid=aggregate(result)
    configs={c['id']:c for c in meta['configurations']}
    findings={scope:{mode:{arch:sorted([r for r in grid if r['scope']==scope and r['mode']==mode and configs[r['config']]['architecture']==arch],
                    key=lambda r:r['median_cagr'] if r['median_cagr'] is not None else -2,reverse=True)[:3]
                    for arch in meta['architecture_labels']} for mode in meta['modes']} for scope in SCOPES}
    (OUTPUT/'findings.json').write_text(json.dumps(findings,allow_nan=False,indent=2),encoding='utf-8')
    with (OUTPUT/'grid.csv').open('w',encoding='utf-8',newline='') as f:
        writer=csv.DictWriter(f,fieldnames=list(grid[0]));writer.writeheader();writer.writerows(grid)
    (OUTPUT/'candidates').mkdir(exist_ok=True)
    by_config={key:[] for key in configs}
    for s in result['instruments']:
        for row in s['rows']:by_config[row[0]].append([s['symbol'],*row])
    for key,rows in by_config.items():
        (OUTPUT/'candidates'/(key+'.js')).write_text('window.step3Summaries=window.step3Summaries||{};window.step3Summaries['+json.dumps(key)+']='+json.dumps(rows,allow_nan=False,separators=(',',':'))+';',encoding='utf-8')
    assets=[{k:v for k,v in s.items() if k not in ('rows','checks')} for s in result['instruments']]
    accounting=json.loads((OUTPUT.parent/'step2/return-check.json').read_text(encoding='utf-8'))
    payload=json.dumps({'metadata':meta,'assets':assets,'grid':grid,'accounting_check':accounting},allow_nan=False,separators=(',',':')).replace('<','\\u003c')
    app=Path(__file__).with_name('report_app.js').read_text(encoding='utf-8')
    (OUTPUT/'report.html').write_text(TEMPLATE.replace('__PLOTLY__',get_plotlyjs()).replace('__APP__',app).replace('__DATA__',payload),encoding='utf-8')
    print(json.dumps({'report':str(OUTPUT/'report.html'),'priority_best':{m:{a:v[0] for a,v in archs.items()} for m,archs in findings['Priority assets'].items()}}),flush=True)


